//contents.history.go.kr/front/km/print.do?levelId=km_011_0020_0030&whereStr="],"verification":"official_question_and_answer_checked"},{"id":"exam78-q17-option-5","era":"고려","category":"불교","curriculum":"고려 복습","prompt":"의천이 교학의 이론 공부와 수행을 함께 강조하며 제시한 것은 __BLANK__이다.","answers":["교관겸수"],"explanation":"교와 관을 함께 닦는다는 뜻이다.","contrast":"지눌의 정혜쌍수와 이름을 바꾸지 않는다.","sources":[{"round":78,"question":17,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/km/print.do?levelId=km_011_0020_0030&whereStr="],"verification":"official_question_and_answer_checked"},{"id":"exam78-q18-option-1","era":"고려","category":"왕과 정치","curriculum":"고려 복습","prompt":"고려 성종에게 시무 28조를 올려 유교적 정치와 지방 통치 정비를 건의한 인물은 __BLANK__이다.","answers":["최승로"],"explanation":"최승로-성종을 한 쌍으로 외운다.","contrast":"이자겸은 인종 때 외척.","sources":[{"round":78,"question":18,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_n204100"],"verification":"official_question_and_answer_checked"},{"id":"exam78-q18-option-2","era":"고려 말","category":"과학과 군사","curriculum":"고려 복습","prompt":"우왕 때 화통도감 설치를 건의해 화약 무기 제조를 이끈 인물은 __BLANK__이다.","answers":["최무선"],"explanation":"화약·화통도감·진포 전투를 연결한다.","contrast":"최영은 홍산, 이성계는 황산.","sources":[{"round":78,"question":18,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_n204100"],"verification":"official_question_and_answer_checked"},{"id":"exam78-q18-option-3","era":"고려","category":"사건과 인물","curriculum":"고려 복습","prompt":"1009년 목종을 폐위하고 현종을 세웠으며 거란 제2차 침입의 구실이 된 정변의 주도자는 __BLANK__이다.","answers":["강조"],"explanation":"강조의 정변과 현종 때 거란 침입을 연결한다.","contrast":"1170년 의종을 폐위한 사건은 무신정변.","sources":[{"round":78,"question":18,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_n204100"],"verification":"official_question_and_answer_checked"},{"id":"exam78-q18-option-4","era":"고려","category":"정치와 대외 관계","curriculum":"고려 복습","prompt":"인종 때 서경 천도와 칭제건원·금 정벌을 주장하다가 대위국을 내세워 봉기한 승려는 __BLANK__이다.","answers":["묘청"],"explanation":"1135년 서경 봉기와 김부식의 진압이다.","contrast":"이자겸의 난은 1126년 외척과 왕권 충돌.","sources":[{"round":78,"question":18,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_n204100"],"verification":"official_question_and_answer_checked"},{"id":"exam78-q18-option-5","era":"고려","category":"통치 기구","curriculum":"고려 복습","prompt":"이의민을 제거한 뒤 권력을 잡고 교정도감의 초대 교정별감이 된 무신 집권자는 __BLANK__이다.","answers":["최충헌"],"explanation":"교정도감은 최씨 정권의 권력 기구다.","contrast":"정중부·이자겸·묘청의 직책으로 연결하지 않는다.","sources":[{"round":78,"question":18,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_n204100"],"verification":"official_question_and_answer_checked"},{"id":"exam78-q19-stem","era":"조선 전기 · 15세기","category":"왕·계승","prompt":"금성대군과 사육신이 복위시키려 했던 왕은 __BLANK__이다. 이 왕은 1452~1455년 재위했으며 수양대군에게 왕위를 넘겼다.","answers":["단종"],"explanation":"지문의 복위 대상은 단종이다. 순흥의 금성대군 복위 모의는 단종 퇴위 뒤인 세조 때 1457년에 일어났다.","contrast":"복위 운동 당시 왕은 세조이지만, 빈칸 왕은 복위 대상인 단종이다.","sources":[{"round":78,"question":19,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0013661"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q19-option-1","era":"조선 전기 · 단종","category":"사건","prompt":"1453년 단종 때 계유정난 뒤 파면된 함길도 도절제사 __BLANK__은 반란을 일으켰다.","answers":["이징옥"],"explanation":"수양대군은 김종서를 제거한 뒤 이징옥도 파면했다. 이징옥의 난은 단종 재위 중 사건이다.","contrast":"이괄의 난은 인조 때 1624년이다.","sources":[{"round":78,"question":19,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0046156"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q19-option-2","era":"조선 후기 · 인조","category":"사건","prompt":"1624년 인조 때 반정의 공신이었던 __BLANK__이 반란을 일으켜 한양을 점령했다.","answers":["이괄"],"explanation":"인조반정 뒤 논공행상과 역모 의심 등에 대한 불만이 반란으로 이어졌다.","contrast":"1453년 단종 때 함길도에서 일어난 이징옥의 난과 구별한다.","sources":[{"round":78,"question":19,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q19-option-3","era":"조선 후기 · 숙종","category":"붕당·환국","prompt":"1680년 숙종 때 허적·윤휴 등 남인이 대거 밀려나고 서인이 집권한 정국 교체는 __BLANK__이다.","answers":["경신환국","경신대출척"],"explanation":"숙종의 환국 중 첫 번째인 경신환국이다. 남인에서 서인으로 권력이 이동했다.","contrast":"1689년 기사환국은 서인이 밀려나고 남인이 집권한다.","sources":[{"round":78,"question":19,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?code=kc_age_30&levelId=kc_i300700"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q19-option-4","era":"조선 전기 · 중종","category":"사림·사화","prompt":"위훈 삭제 등의 개혁을 추진한 조광조 세력이 1519년 중종 때 제거된 사건은 __BLANK__이다.","answers":["기묘사화"],"explanation":"조광조의 개혁에 대한 훈구 세력의 반발 등이 사림 탄압으로 이어졌다.","contrast":"선조 때 정여립 사건과 관련된 기축옥사와 구별한다.","sources":[{"round":78,"question":19,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q19-option-5","era":"조선 전기 · 선조","category":"붕당·옥사","prompt":"1589년 선조 때 정여립의 모반 혐의를 계기로 동인이 대규모로 탄압받은 사건은 __BLANK__이다.","answers":["기축옥사"],"explanation":"정여립 사건을 빌미로 동인 세력이 큰 타격을 받았다.","contrast":"1519년 중종·조광조·기묘사화와 왕·인물·연대를 묶어 구별한다.","sources":[{"round":78,"question":19,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q20-stem","era":"조선 · 태종 이후","category":"중앙 관청","prompt":"소속 도사들이 금오계첩을 만들었고 금오·조옥이라는 별칭도 있던 조선의 국왕 직속 사법 기관은 __BLANK__이다.","answers":["의금부"],"explanation":"의금부의 신입 도사들은 면신례를 치르고 금오계첩을 나누어 가졌다.","contrast":"금오계첩은 규장각의 학술 모임을 그린 자료가 아니다.","sources":[{"round":78,"question":20,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?code=kc_age_30&levelId=kc_o301010"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q20-option-1","era":"조선","category":"중앙 관청","prompt":"조선의 수도 한양에서 호적·토지·가옥·도로 등 도시 행정과 치안을 담당한 관청은 __BLANK__이다.","answers":["한성부"],"explanation":"한성부는 수도를 운영하는 행정 관청이었다.","contrast":"왕명에 따라 반역죄 등을 심리한 의금부와 구별한다.","sources":[{"round":78,"question":20,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q20-option-2","era":"조선 · 세조 이후","category":"중앙 관청","prompt":"천문 관측·지리·역법·기후 등에 관한 사무를 맡았으며 세조 때 서운관에서 이름이 바뀐 관청은 __BLANK__이다.","answers":["관상감"],"explanation":"천문·기상·시간 측정 등 전문 기술 업무를 담당했다.","contrast":"사법 관청 의금부나 학술 기관 규장각의 업무가 아니다.","sources":[{"round":78,"question":20,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0004874"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q20-option-3","era":"조선 후기 · 정조","category":"중앙 관청","prompt":"정조가 활용한 학술 기관으로 제학·직제학 외에 검서관을 두고 이덕무·박제가·유득공 등 서얼을 기용한 곳은 __BLANK__이다.","answers":["규장각"],"explanation":"검서관이 기관 판별의 핵심 단서다. 정조는 규장각을 학술과 인재 양성의 기반으로 활용했다.","contrast":"제학·직제학만 보고 집현전이나 홍문관으로 단정하지 않는다.","sources":[{"round":78,"question":20,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/tg/view.do?ganada=%EC%A0%84%EC%B2%B4&levelId=tg_003_2280&pageUnit=10&treeId=0209"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q20-option-4","era":"조선 전기 · 성종 이후","category":"중앙 관청","prompt":"성종 때 기능이 정비되어 왕에게 경전과 역사를 강론하는 경연을 담당하고 학문적 자문을 한 기관은 __BLANK__이다.","answers":["홍문관"],"explanation":"홍문관은 왕의 학습과 정치 자문, 장서 관리 등을 담당했다.","contrast":"의금부는 재판 기관이고 규장각의 검서관은 정조와 연결한다.","sources":[{"round":78,"question":20,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/hm/view.do?levelId=hm_075_0030"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q20-option-5","era":"조선 · 태종 이후","category":"중앙 관청","prompt":"왕명을 받아 반역죄·강상죄와 관원의 중대 범죄를 조사하고 심리한 국왕 직속 특별 사법 기관은 __BLANK__이다.","answers":["의금부"],"explanation":"의금부는 태종 때인 1414년 이 이름으로 정비되었다.","contrast":"수도의 일반 행정·치안 담당 기관인 한성부와 구별한다.","sources":[{"round":78,"question":20,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?code=kc_age_30&levelId=kc_o301010"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q21-stem","era":"조선 전기 · 세종~성종","category":"인물·외교","prompt":"일본에 직접 다녀온 경험을 바탕으로 일본의 지리·정치·풍속 등을 정리한 『해동제국기』를 쓴 인물은 __BLANK__이다.","answers":["신숙주"],"explanation":"신숙주는 세종 때 학술 사업, 성종 때 외교서 편찬 등 여러 왕대에 걸쳐 활동했다.","contrast":"서원 건립의 주세붕이나 예학의 김장생과 구별한다.","sources":[{"round":78,"question":21,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0033134"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q21-option-1","era":"조선 전기 · 세종","category":"인물·학술","prompt":"『해동제국기』의 저자이면서 세종 때 『훈민정음 해례』 편찬에도 참여한 언어·외교 전문가 __BLANK__는 15세기 인물이다.","answers":["신숙주"],"explanation":"언어와 음운에 대한 지식, 일본 등과의 외교 활동을 함께 연결한다.","contrast":"신숙주의 활동 시기를 조선 후기 정조의 규장각과 혼동하지 않는다.","sources":[{"round":78,"question":21,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0033134"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q21-option-2","era":"조선 전기 · 중종","category":"교육·서원","prompt":"1543년 중종 때 풍기 군수로서 안향을 모시는 최초의 서원인 백운동 서원을 세운 사람은 __BLANK__이다.","answers":["주세붕"],"explanation":"백운동 서원은 뒤에 소수서원이라는 사액을 받았다.","contrast":"건립은 주세붕, 명종 때 사액을 건의한 사람은 이황이다.","sources":[{"round":78,"question":21,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0053318"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q21-option-3","era":"조선 후기 · 효종","category":"인물·사상","prompt":"효종이 즉위한 1649년 「기축봉사」를 올려 명에 대한 의리와 북벌의 당위성을 강조한 학자는 __BLANK__이다.","answers":["송시열","우암 송시열"],"explanation":"병자호란 이후의 존명·반청 의식과 북벌론에 연결된다.","contrast":"15세기 신숙주가 아니라 17세기 효종과 함께 기억한다.","sources":[{"round":78,"question":21,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0024667"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q21-option-4","era":"조선 전기 · 선조","category":"인물·향약","prompt":"선조 때 해주 지역에서 향약을 시행하여 향촌 교화와 질서 정비를 도모한 율곡 __BLANK__는 16세기 성리학자다.","answers":["이이","율곡 이이"],"explanation":"해주 향약은 이이와 연결한다.","contrast":"예안 향약은 이황, 백운동 서원 건립은 주세붕이다.","sources":[{"round":78,"question":21,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/mid/hm_087_0020?tabId=r"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q21-option-5","era":"조선 · 선조","category":"인물·예학","prompt":"1599년 선조 때 『가례집람』을 편찬하여 주자의 『가례』를 검토·보완한 예학자는 __BLANK__이다.","answers":["김장생","사계 김장생"],"explanation":"김장생은 이이의 문인이며 예학 발전에 큰 영향을 주었다.","contrast":"저자의 편찬 시기와 1685년 간행 시기는 구별한다.","sources":[{"round":78,"question":21,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0000127"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q22-stem","era":"조선 · 선조","category":"전쟁","prompt":"1592년 김시민이 진주성을 지키며 일본군에 맞선 제1차 진주성 전투는 __BLANK__ 중에 일어났다.","answers":["임진왜란"],"explanation":"지문의 진주·김시민·진천뢰가 임진왜란을 가리킨다.","contrast":"같은 전쟁 중 사건을 묻는 것이므로 정답이 같은 해일 필요는 없다.","sources":[{"round":78,"question":22,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q22-option-1","era":"조선 후기 · 인조","category":"전쟁·장수","prompt":"1627년 정묘호란 때 용골산성에서 의병을 이끌어 후금군에 맞선 장수는 __BLANK__이다.","answers":["정봉수"],"explanation":"정묘호란의 대표적 의병장과 전투 장소를 함께 연결한다.","contrast":"김시민·진주와 권율·행주는 선조 때 임진왜란이다.","sources":[{"round":78,"question":22,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/kc/printViewPopup.do?levelId=kc_i305600"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q22-option-2","era":"조선 후기 · 인조","category":"전쟁·장수","prompt":"1637년 병자호란 때 남한산성의 인조를 구원하러 진군하여 광교산에서 청군을 물리친 장수는 __BLANK__이다.","answers":["김준룡"],"explanation":"전라 병사 김준룡의 광교산 전투는 병자호란의 전투다.","contrast":"정봉수의 용골산성은 1627년 정묘호란이다.","sources":[{"round":78,"question":22,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://sillok.history.go.kr/id/kpa_11501005_003"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q22-option-3","era":"조선 전기 · 세종","category":"영토·장수","prompt":"세종 때 두만강 일대의 여진을 몰아내고 6진 개척을 주도한 장수는 __BLANK__이다.","answers":["김종서"],"explanation":"6진은 조선 전기 북방 영토 정비와 연결된다.","contrast":"이종무는 남쪽 대마도 정벌, 최윤덕은 압록강 방면 4군과 연결한다.","sources":[{"round":78,"question":22,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q22-option-4","era":"조선 · 선조","category":"전쟁·장수","prompt":"1593년 임진왜란 중 행주산성에서 일본군을 크게 물리친 장수는 __BLANK__이다.","answers":["권율"],"explanation":"행주 대첩은 진주 대첩·한산도 대첩과 함께 임진왜란의 주요 승리다.","contrast":"인조 때 청군과 싸운 김준룡의 광교산 전투와 구별한다.","sources":[{"round":78,"question":22,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q22-option-5","era":"조선 전기 · 세종","category":"대외 관계·장수","prompt":"1419년 세종 때 왜구의 근거지를 공격하기 위해 대마도 정벌을 이끈 장수는 __BLANK__이다.","answers":["이종무"],"explanation":"대마도 정벌은 세종 때의 대외 정책이다.","contrast":"왜구·일본이 등장해도 모두 16세기 선조 때 임진왜란은 아니다.","sources":[{"round":78,"question":22,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q23-stem","era":"조선 후기 · 효종","category":"대외 관계·사건","prompt":"효종 때 청의 요청으로 조총 부대를 파견하여 러시아 세력과 싸운 1654년·1658년의 원정은 __BLANK__이다.","answers":["나선 정벌","나선정벌"],"explanation":"1차 변급, 2차 신유가 지휘했다. 지문의 조총병 100명 요청은 제1차 정벌에 해당한다.","contrast":"청을 공격하려는 북벌 구상과 러시아를 공격한 실제 나선 정벌을 구별한다.","sources":[{"round":78,"question":23,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/kc/printViewPopup.do?levelId=kc_i301900"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q23-option-1","era":"조선 후기 · 17세기","category":"연표·왕","prompt":"1623년 인조반정과 1680년 경신환국 사이에 재위했고, 북벌론과 1654·1658년 나선 정벌에 연결되는 왕은 __BLANK__이다.","answers":["효종"],"explanation":"나선 정벌은 23번 연표의 (가) 구간에 들어간다.","contrast":"18세기 영조·정조의 탕평 시대와 구별한다.","sources":[{"round":78,"question":23,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/kc/printViewPopup.do?levelId=kc_i301900"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q23-option-2","era":"조선 후기 · 숙종~영조","category":"연표·사건","prompt":"1680년 경신환국과 1728년 이인좌의 난 사이 구간의 시작 사건인 __BLANK__에서는 남인이 밀려나고 서인이 집권했다.","answers":["경신환국","경신대출척"],"explanation":"23번 (나)는 1680~1728년으로, 효종의 나선 정벌보다 뒤다.","contrast":"나선 정벌은 이 구간 앞인 인조반정~경신환국 사이에 놓는다.","sources":[{"round":78,"question":23,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?code=kc_age_30&levelId=kc_i300700"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q23-option-3","era":"조선 후기 · 영조~정조","category":"연표·사건","prompt":"정조 때 장용영이 만들어지기 전, 영조 즉위 초기인 1728년에 벌어져 연표 (다)의 시작점이 되는 반란은 __BLANK__이다.","answers":["이인좌의 난","무신란"],"explanation":"(다)는 이인좌의 난부터 정조의 장용영 창설까지인 18세기 구간이다.","contrast":"17세기 효종의 나선 정벌은 이미 앞선 시기에 끝났다.","sources":[{"round":78,"question":23,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q23-option-4","era":"조선 후기 · 정조~순조","category":"연표·군사","prompt":"정조가 왕권을 뒷받침하기 위해 마련한 친위 군영 __BLANK__의 창설과 순조 때 홍경래의 난 사이가 연표 (라) 구간이다.","answers":["장용영"],"explanation":"장용위에서 출발하여 장용영으로 확대되었고 1793년 내영·외영 체제로 정비되었다.","contrast":"선조 때 임진왜란 중 만든 훈련도감과 구별한다.","sources":[{"round":78,"question":23,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/hm/view.do?levelId=hm_098_0030"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q23-option-5","era":"조선 후기 · 순조~고종","category":"연표·사건","prompt":"1811년 순조 때 평안도 차별과 세도 정치의 문제를 배경으로 일어난 __BLANK__부터 1866년 고종 때 병인양요까지가 연표 (마) 구간이다.","answers":["홍경래의 난"],"explanation":"(마)는 19세기 구간으로 나선 정벌이 있었던 17세기와 다르다.","contrast":"1728년 영조 때 이인좌의 난과 구별한다.","sources":[{"round":78,"question":23,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q24-stem","era":"조선 후기 · 정조","category":"왕·왕실","prompt":"아버지 사도세자의 묘를 수원으로 옮겨 현륭원을 조성하고, 이후 수원 화성을 건설한 조선 후기 왕은 __BLANK__이다.","answers":["정조"],"explanation":"사도세자의 아들이자 영조의 손자라는 가족 관계가 핵심 단서다.","contrast":"공민왕은 14세기 고려의 왕이며 정조는 18세기 조선의 왕이다.","sources":[{"round":78,"question":24,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/hm/view.do?levelId=hm_098_0030"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q24-option-1","era":"조선 후기 · 경종","category":"왕·계승","prompt":"1721년 동생 연잉군, 곧 뒤의 영조를 왕세제로 책봉한 왕은 __BLANK__이다.","answers":["경종"],"explanation":"왕의 동생인 후계자는 왕세제라 한다.","contrast":"정조는 영조의 손자이므로 연잉군 책봉의 주체가 아니다.","sources":[{"round":78,"question":24,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0002808"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q24-option-2","era":"조선 후기 · 숙종","category":"왕·국경","prompt":"1712년 청과의 국경을 정한 백두산정계비가 세워진 때의 조선 왕은 __BLANK__이다.","answers":["숙종","조선 숙종"],"explanation":"백두산정계비는 18세기 초 조선 숙종 때의 대청 관계와 연결된다.","contrast":"고려 숙종의 은병 주조나 정조의 수원 화성과 구별한다.","sources":[{"round":78,"question":24,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q24-option-3","era":"조선 · 선조","category":"군사 제도","prompt":"1593년 선조 때 임진왜란에 대응하기 위해 포수·사수·살수의 삼수병으로 편성한 군사 기관은 __BLANK__이다.","answers":["훈련도감"],"explanation":"임진왜란 중 군사 체계를 보완하기 위해 창설했다.","contrast":"정조의 친위 군영은 장용영이다.","sources":[{"round":78,"question":24,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q24-option-4","era":"조선 후기 · 영조","category":"왕·탕평","prompt":"탕평을 내세우고 1742년 성균관 앞에 탕평비를 세워 붕당 간 대립을 줄이려 한 왕은 __BLANK__이다.","answers":["영조"],"explanation":"탕평비는 영조의 구체적 정책을 식별하는 단서다.","contrast":"정조도 탕평을 추진했지만 탕평비 건립은 영조의 업적이다.","sources":[{"round":78,"question":24,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0058858"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q24-option-5","era":"조선 후기 · 정조","category":"인재 양성","prompt":"정조가 1781년부터 젊고 유능한 문신을 선발해 규장각에서 재교육한 제도는 __BLANK__이다.","answers":["초계문신제","초계문신제도","초계문신 제도"],"explanation":"학문과 정책 역량을 키워 개혁을 뒷받침할 관료를 양성했다.","contrast":"군사 기반인 장용영, 학술 기관인 규장각과 역할을 나누어 기억한다.","sources":[{"round":78,"question":24,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0056940"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q25-stem","era":"조선 후기 · 정조","category":"경제·화폐","prompt":"상평통보의 유통이 원활하지 않다는 전황 문제에 대응하여 십전통보를 함께 쓰자는 정동교의 건의는 1793년 __BLANK__ 재위기에 나왔다.","answers":["정조"],"explanation":"문항의 대화는 정조실록 17년 12월 1일 기사와 일치한다.","contrast":"십전통보라는 이름만 보고 효종 때라고 단정하지 않는다.","sources":[{"round":78,"question":25,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://sillok.history.go.kr/id/kva_11712001_006"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q25-option-1","era":"고려 · 숙종","category":"경제·화폐","prompt":"1101년 고려 숙종 때 주조한 은병은 입구가 넓은 모양 때문에 __BLANK__라고도 불렸다.","answers":["활구"],"explanation":"고려의 은병이므로 18세기 정조 때 조선 후기 경제 모습으로는 맞지 않는다.","contrast":"고려 숙종의 은병·해동통보와 조선 숙종 때의 상평통보 유통을 구별한다.","sources":[{"round":78,"question":25,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/km/view.do?levelId=km_008_0030_0010_0040"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q25-option-2","era":"조선 후기","category":"경제·대동법","prompt":"대동법 시행 뒤 관청에서 필요한 물품을 구매해 조달하는 역할을 한 상인은 __BLANK__이다.","answers":["공인"],"explanation":"대동법은 광해군 때 시작되어 조선 후기에 확대되었다. 공인의 구매 활동은 상품 생산과 유통을 촉진했다.","contrast":"청과 교역한 만상이나 장시를 순회한 보부상과 담당 역할이 다르다.","sources":[{"round":78,"question":25,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q25-option-3","era":"조선 후기","category":"경제·상인","prompt":"개성의 송상과 함께 대청 무역으로 성장했으며 의주를 활동 근거지로 삼은 상인 집단은 __BLANK__이다.","answers":["만상","의주 만상"],"explanation":"송상은 개성, 만상은 의주와 연결한다. 두 집단의 활동은 조선 후기 사상의 성장에 해당한다.","contrast":"동래 내상은 대일 무역, 한강 경강상인은 운송·상업 활동으로 구별한다.","sources":[{"round":78,"question":25,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q25-option-4","era":"조선 후기","category":"경제·유통","prompt":"조선 후기에 여러 지역의 장시를 돌아다니며 상품을 판매하여 지역 시장들을 연결한 행상은 __BLANK__이다.","answers":["보부상","부보상"],"explanation":"정기 시장인 장시의 확대와 상품 유통의 성장 속에서 활동했다.","contrast":"관청에 필요한 물품을 조달한 공인과 거래 상대·방식을 구별한다.","sources":[{"round":78,"question":25,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q25-option-5","era":"조선 후기 · 효종 이후","category":"경제·광업","prompt":"1651년 효종 때 시행되어 관이 광물 채굴을 허가하고 민간에게 채굴을 맡긴 뒤 세금을 거둔 제도는 __BLANK__이다.","answers":["설점수세제","설점수세"],"explanation":"민간의 광산 채굴 참여와 정부의 세금 징수를 결합한 제도다.","contrast":"정조 때 처음 시작된 제도는 아니어도 정조 시기의 경제 모습으로 제시할 수 있다.","sources":[{"round":78,"question":25,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/tg/view.do?ganada=&levelId=tg_003_1920&pageUnit=10&subjectCode=tg_ty_090&tabId=02"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q26-stem","era":"조선 후기 · 19세기","category":"인물·서화","prompt":"제주 유배 생활을 했으며 독창적인 추사체를 발전시키고 「불이선란도」를 남긴 서화가는 __BLANK__이다.","answers":["김정희","추사 김정희","추사"],"explanation":"김정희는 19세기 서예·금석학·문인화의 대표 인물이다.","contrast":"추사체·불이선란도·세한도를 한 인물의 묶음으로 기억한다.","sources":[{"round":78,"question":26,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_r300670"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q26-option-1","era":"조선 후기","category":"미술·작가","prompt":"달밤에 담장 곁에서 만나는 남녀를 그린 「월하정인」의 작가로, 남녀의 애정과 도시 풍속을 섬세하게 묘사한 화가는 __BLANK__이다.","answers":["신윤복","혜원 신윤복"],"explanation":"26번 첫 번째 그림은 신윤복의 월하정인이다.","contrast":"김정희의 세한도는 남녀 풍속 장면이 아니라 집과 겨울 나무를 그린 문인화다.","sources":[{"round":78,"question":26,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q26-option-2","era":"조선 후기 · 19세기","category":"미술·작가","prompt":"매화에 둘러싸인 초가집과 그 안팎의 인물을 그린 「매화초옥도」의 작가는 __BLANK__이다.","answers":["전기","고람 전기"],"explanation":"26번 두 번째 그림은 전기의 매화초옥도이며 국립중앙박물관 소장품이다.","contrast":"조희룡의 매화서옥도와 제목이 비슷하지만 작가·작품은 다르다.","sources":[{"round":78,"question":26,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://www.museum.go.kr/MUSEUM/contents/M0502000000.do?relicId=8338&schM=view&searchId=search"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q26-option-3","era":"조선 후기","category":"미술·작가","prompt":"거대한 절벽과 폭포, 배를 탄 어부가 등장하는 「산수인물도」를 그렸으며 풍속화에도 뛰어났던 단원 __BLANK__는 산수화도 많이 남겼다.","answers":["김홍도","단원 김홍도"],"explanation":"26번 세 번째 그림은 김홍도 필 산수인물도다.","contrast":"김홍도를 씨름·서당만으로 외우지 말고 산수화도 그렸음을 기억한다. 강희안의 고사관수도와도 다르다.","sources":[{"round":78,"question":26,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0073045"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q26-option-4","era":"조선 후기","category":"미술·작가","prompt":"고양이가 병아리를 물고 달아나자 부부와 닭들이 놀라는 순간을 그린 「파적도」의 작가는 __BLANK__이다.","answers":["김득신","긍재 김득신"],"explanation":"고요함이 깨진다는 제목과 역동적인 장면을 연결한다.","contrast":"서민 생활을 그렸다는 이유만으로 모든 풍속화를 김홍도의 작품으로 보면 안 된다.","sources":[{"round":78,"question":26,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0059590"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q26-option-5","era":"조선 후기 · 헌종","category":"미술·작품","prompt":"김정희가 1844년 제주 유배 중에도 책을 보내준 이상적에게 감사하며 집과 소나무·잣나무를 그려 준 작품은 __BLANK__이다.","answers":["세한도"],"explanation":"헌종 10년에 그린 작품이다. 추운 때에도 변치 않는 나무와 제자의 신의를 연결한다.","contrast":"김정희의 불이선란도는 난초 그림이며, 세한도는 집과 나무가 있는 가로로 긴 화면이다.","sources":[{"round":78,"question":26,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_r300670"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q27-stem","era":"조선 후기 · 정조","category":"사회·향촌","prompt":"1785년 정조가 금지하려 했던, 지방의 구향과 신향이 향임과 향촌 운영의 주도권을 둘러싸고 다투는 현상은 __BLANK__이다.","answers":["향전"],"explanation":"지문은 일성록 정조 9년 9월 6일의 전교와 일치한다.","contrast":"향약은 마을 규약이고, 향전은 향촌 지배권을 둘러싼 다툼이다.","sources":[{"round":78,"question":27,"part":"stem","option":null}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/hm/view.do?levelId=hm_107_0030&tabId=03&treeId=010603"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q27-option-1","era":"고려 · 문종","category":"교육·인물","prompt":"11세기 중엽 고려 문종 때 9재 학당을 열어 문헌공도라는 사학을 발전시킨 유학자는 __BLANK__이다.","answers":["최충"],"explanation":"고려 사학의 성장과 귀족 교육의 발전을 보여 주는 사례다.","contrast":"16세기 중종 때 주세붕의 백운동 서원과 나라·시기가 다르다.","sources":[{"round":78,"question":27,"part":"option","option":1}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/hm/view.do?levelId=hm_066_0030"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q27-option-2","era":"조선 후기","category":"사회·신분","prompt":"양반의 첩 자손인 서얼이 청요직 진출 등의 제한을 없애 달라고 요구한 조선 후기의 신분 상승 운동은 __BLANK__이다.","answers":["통청 운동","서얼 통청 운동","통청운동"],"explanation":"기존 신분 질서의 제약을 완화하려는 요구로 조선 후기 사회 변화에 속한다.","contrast":"지방의 구향·신향 대립인 향전과는 구체적 쟁점이 다르지만 같은 시대 변화 속에서 이해할 수 있다.","sources":[{"round":78,"question":27,"part":"option","option":2}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://contents.history.go.kr/front/tg/view.do?ganada=%EC%9E%90&levelId=tg_003_0610&pageUnit=20&treeId=0105","https://contents.history.go.kr/front/tg/view.do?ganada=%EC%A0%84%EC%B2%B4&levelId=tg_003_2280&pageUnit=10&treeId=0209"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q27-option-3","era":"고려 후기 · 원 간섭기","category":"사회·풍속","prompt":"변발과 호복이 지배층을 중심으로 유행한 13~14세기 고려의 대외 관계상 시기를 __BLANK__라고 한다.","answers":["원 간섭기","원간섭기"],"explanation":"원의 영향이 고려 왕실과 지배층의 생활에 미친 시기다. 뒤에 공민왕은 몽골풍을 없애려 했다.","contrast":"18세기 조선 정조 때의 향전·통청 운동과 구별한다.","sources":[{"round":78,"question":27,"part":"option","option":3}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q27-option-4","era":"고려 · 명종","category":"사회·봉기","prompt":"1176년 명종 때 공주 명학소 주민들이 차별과 수탈에 저항해 일으킨 봉기는 __BLANK__이다.","answers":["망이·망소이의 난","망이 망소이의 난","망이 망소이의 봉기","망이·망소이의 봉기"],"explanation":"고려 무신 집권기에 일어난 하층민의 봉기다.","contrast":"조선 후기 신향의 향권 다툼이나 서얼 통청 운동과 시대·집단이 다르다.","sources":[{"round":78,"question":27,"part":"option","option":4}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"},{"id":"exam78-q27-option-5","era":"고려 · 고종","category":"의학·문헌","prompt":"고려 고종 때 우리나라에서 나는 약재를 이용한 질병 치료와 처방을 정리한, 현존하는 가장 오래된 우리 의학서로 알려진 책은 __BLANK__이다.","answers":["향약구급방"],"explanation":"13세기 고려의 의학서로, 향약은 우리 땅의 약재라는 뜻이다.","contrast":"향약구급방의 향약(鄕藥)은 마을 규약인 향약(鄕約)과 한자·의미가 다르다.","sources":[{"round":78,"question":27,"part":"option","option":5}],"evidenceUrls":["https://www.historyexam.go.kr/pst/view.do?bbs=dat&pst_sno=1000030119","https://encykorea.aks.ac.kr/Article/E0062951"],"curriculum":"조선 복습","verification":"official_question_and_answer_checked"}]};
